using System;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class DepartmentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly DepartmentsController _controller;

        public DepartmentsControllerTests()
        {
            _context = TestDbContextHelper.CreateSeededContext();
            _controller = new DepartmentsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsViewWithDepartments()
        {
            var result = _controller.Index();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<System.Collections.Generic.List<Department>>(viewResult.Model);
            Assert.True(model.Count > 0);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithDepartment()
        {
            var deptId = _context.Departments.First().DepartmentID;

            var result = _controller.Details(deptId);

            var viewResult = Assert.IsType<ViewResult>(result);
            var dept = Assert.IsType<Department>(viewResult.Model);
            Assert.Equal(deptId, dept.DepartmentID);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Details(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Create_Get_ReturnsView()
        {
            var result = _controller.Create();

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void Create_Post_ValidDepartment_RedirectsToIndex()
        {
            var instructor = _context.Instructors.First();
            var dept = new Department
            {
                Name = "New Department",
                Budget = 200000,
                StartDate = DateTime.Parse("2023-01-01"),
                InstructorID = instructor.ID
            };

            var result = _controller.Create(dept);

            var redirectResult = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirectResult.ActionName);
        }

        [Fact]
        public void Create_Post_ValidDepartment_SavesToDB()
        {
            var instructor = _context.Instructors.First();
            var dept = new Department
            {
                Name = "Saved Department",
                Budget = 150000,
                StartDate = DateTime.Parse("2023-01-01"),
                InstructorID = instructor.ID
            };

            _controller.Create(dept);

            var saved = _context.Departments.FirstOrDefault(d => d.Name == "Saved Department");
            Assert.NotNull(saved);
            Assert.Equal(150000m, saved!.Budget);
            Assert.Equal(instructor.ID, saved.InstructorID);
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("Name", "Required");
            var dept = new Department();

            var result = _controller.Create(dept);

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithDepartment()
        {
            var deptId = _context.Departments.First().DepartmentID;

            var result = _controller.Edit(deptId);

            var viewResult = Assert.IsType<ViewResult>(result);
            var dept = Assert.IsType<Department>(viewResult.Model);
            Assert.Equal(deptId, dept.DepartmentID);
        }

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Edit(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Post_ValidDepartment_RedirectsToIndex()
        {
            var existingDept = _context.Departments.First();
            _context.Entry(existingDept).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var dept = new Department
            {
                DepartmentID = existingDept.DepartmentID,
                Name = "Updated",
                Budget = existingDept.Budget,
                StartDate = existingDept.StartDate,
                InstructorID = existingDept.InstructorID
            };

            var result = _controller.Edit(dept);

            var redirectResult = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirectResult.ActionName);
        }

        [Fact]
        public void Edit_Post_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("Name", "Required");
            var dept = new Department { DepartmentID = 1 };

            var result = _controller.Edit(dept);

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithDepartment()
        {
            var deptId = _context.Departments.First().DepartmentID;

            var result = _controller.Delete(deptId);

            var viewResult = Assert.IsType<ViewResult>(result);
            var dept = Assert.IsType<Department>(viewResult.Model);
            Assert.Equal(deptId, dept.DepartmentID);
        }

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_Get_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Delete(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void DeleteConfirmed_RemovesDepartmentAndRedirects()
        {
            var dept = _context.Departments.First();
            var deptId = dept.DepartmentID;
            var initialCount = _context.Departments.Count();

            var result = _controller.DeleteConfirmed(deptId);

            var redirectResult = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirectResult.ActionName);
            Assert.Equal(initialCount - 1, _context.Departments.Count());
        }
    }
}

