using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestDbContextHelper.CreateSeededContext();
            _controller = new InstructorsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_NoParams_ReturnsViewWithInstructorIndexData()
        {
            var result = _controller.Index(null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
            Assert.NotNull(model.Instructors);
            Assert.True(model.Instructors.Any());
        }

        [Fact]
        public void Index_WithInstructorId_PopulatesCourses()
        {
            var instructor = _context.Instructors
                .First(i => _context.CourseAssignments.Any(ca => ca.InstructorID == i.ID));

            var result = _controller.Index(instructor.ID, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
            Assert.NotNull(model.Courses);
            Assert.True(model.Courses.Any());
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithInstructor()
        {
            var instructorId = _context.Instructors.First().ID;

            var result = _controller.Details(instructorId);

            var viewResult = Assert.IsType<ViewResult>(result);
            var instructor = Assert.IsType<Instructor>(viewResult.Model);
            Assert.Equal(instructorId, instructor.ID);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Details(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Create_Get_ReturnsViewWithInstructor()
        {
            var result = _controller.Create();

            var viewResult = Assert.IsType<ViewResult>(result);
            var instructor = Assert.IsType<Instructor>(viewResult.Model);
            Assert.NotNull(instructor.CourseAssignments);
            Assert.Empty(instructor.CourseAssignments);
        }

        [Fact]
        public void Create_Post_ValidInstructor_RedirectsToIndex()
        {
            var instructor = new Instructor
            {
                FirstMidName = "NewInstr",
                LastName = "TestLast",
                HireDate = DateTime.Parse("2020-01-01")
            };

            var result = _controller.Create(instructor, null);

            var redirectResult = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirectResult.ActionName);
        }

        [Fact]
        public void Create_Post_ValidInstructor_SavesToDB()
        {
            var instructor = new Instructor
            {
                FirstMidName = "SavedInstr",
                LastName = "SavedLast",
                HireDate = DateTime.Parse("2020-01-01")
            };

            _controller.Create(instructor, null);

            var saved = _context.Instructors.FirstOrDefault(i => i.LastName == "SavedLast");
            Assert.NotNull(saved);
            Assert.Equal("SavedInstr", saved!.FirstMidName);
            Assert.Equal(DateTime.Parse("2020-01-01"), saved.HireDate);
        }

        [Fact]
        public void Create_Post_WithSelectedCourses_AddsCourseAssignments()
        {
            var course = _context.Courses.First();
            var instructor = new Instructor
            {
                FirstMidName = "WithCourse",
                LastName = "InstrTest",
                HireDate = DateTime.Parse("2020-01-01")
            };

            var selectedCourses = new[] { course.CourseID.ToString() };
            _controller.Create(instructor, selectedCourses);

            var saved = _context.Instructors.FirstOrDefault(i => i.LastName == "InstrTest");
            Assert.NotNull(saved);
            Assert.NotNull(saved!.CourseAssignments);
            Assert.Single(saved.CourseAssignments);
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("LastName", "Required");
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                HireDate = DateTime.Parse("2020-01-01")
            };

            var result = _controller.Create(instructor, null);

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithInstructor()
        {
            var instructorId = _context.Instructors.First().ID;

            var result = _controller.Delete(instructorId);

            var viewResult = Assert.IsType<ViewResult>(result);
            var instructor = Assert.IsType<Instructor>(viewResult.Model);
            Assert.Equal(instructorId, instructor.ID);
        }

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_Get_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Delete(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void DeleteConfirmed_RemovesInstructorAndRedirects()
        {
            // Create a standalone instructor not assigned to any department to simplify
            var instructor = new Instructor
            {
                FirstMidName = "ToDelete",
                LastName = "DeleteMe",
                HireDate = DateTime.Parse("2020-01-01"),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            // Need the OfficeAssignment to be loadable
            _context.Entry(instructor).Collection(i => i.CourseAssignments).Load();

            var result = _controller.DeleteConfirmed(instructor.ID);

            var redirectResult = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirectResult.ActionName);
            Assert.Null(_context.Instructors.Find(instructor.ID));
        }

        [Fact]
        public void DeleteConfirmed_ClearsDepartmentAdministrator()
        {
            // Create an instructor who's a department admin
            var instructor = new Instructor
            {
                FirstMidName = "DeptAdmin",
                LastName = "ToRemove",
                HireDate = DateTime.Parse("2020-01-01"),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var dept = new Department
            {
                Name = "TempDept",
                Budget = 100000,
                StartDate = DateTime.Now,
                InstructorID = instructor.ID
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            _controller.DeleteConfirmed(instructor.ID);

            var updatedDept = _context.Departments.Find(dept.DepartmentID);
            Assert.NotNull(updatedDept);
            Assert.Null(updatedDept!.InstructorID);
        }
    }
}

