        [Fact]
        public void DeleteConfirmed_RemovesCourseAndRedirects()
        {
            var course = _context.Courses.First();
            var courseId = course.CourseID;
            var initialCount = _context.Courses.Count();

            var result = _controller.DeleteConfirmed(courseId);

            var redirectResult = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirectResult.ActionName);
            Assert.Equal(initialCount - 1, _context.Courses.Count());
        }

        [Fact]
        public void Index_ReturnsAllCoursesWithDepartments()
        {
            var result = _controller.Index();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<System.Collections.Generic.List<Course>>(viewResult.Model);
            Assert.Equal(2, model.Count); // We seeded 2 courses
            Assert.All(model, c => Assert.NotNull(c.Department));
        }

        [Fact]
        public void Details_ReturnsCourseWithDepartment()
        {
            var courseId = _context.Courses.First().CourseID;

            var result = _controller.Details(courseId);

            var viewResult = Assert.IsType<ViewResult>(result);
            var course = Assert.IsType<Course>(viewResult.Model);
            Assert.NotNull(course.Department);
            Assert.Equal(courseId, course.CourseID);
            Assert.NotNull(course.Title);
        }

        [Fact]
        public void Create_Post_ValidCourseWithZeroLengthImage_SavesWithoutImage()
        {
            var dept = _context.Departments.First();
            var course = new Course
            {
                CourseID = 6666,
                Title = "No Image Course",
                Credits = 2,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.jpg");
            mockFile.Setup(f => f.Length).Returns(0); // zero length

            var result = _controller.Create(course, mockFile.Object);

            // Zero-length file should be ignored (Length > 0 check)
            var redirectResult = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirectResult.ActionName);
            var saved = _context.Courses.Find(6666);
            Assert.NotNull(saved);
            Assert.Null(saved!.TeachingMaterialImagePath);
        }
    }
}

